import urllib.request,urllib.error,http.cookiejar,json
base='https://app.ontrackegy.com/ayo/'
http=urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
checks=[]
for suffix,marker in [('',b'ayoPlayback'),('app.js?v=10',b'async function sendTurn('),('style.css?v=10',b'.ayo-native-player'),('ayo-mic-stt.js',b'createMicTurns'),('assets/ayo-character.webp',None)]:
 try:
  with http.open(urllib.request.Request(base+suffix),timeout=8) as r:
   body=r.read(180000);pol=r.headers.get_all('Permissions-Policy',[])
   checks.append({'route':suffix or '/','http':r.status,'bytes':len(body),'marker':marker is None or marker in body,'mic_policy':pol if suffix=='' else None})
 except urllib.error.HTTPError as e:checks.append({'route':suffix or '/','http':e.code})
try:
 with http.open(base+'api.php?action=status',timeout=8) as r:
  j=json.load(r);checks.append({'route':'api.php?action=status','http':r.status,'owner_guarded':not j.get('ownerAuthorized',False),'keys_not_leaked':'inworldKey' not in j.get('config',{})})
except urllib.error.HTTPError as e:checks.append({'route':'api.php?action=status','http':e.code})
with http.open(base,timeout=8) as r:pol=r.headers.get_all('Permissions-Policy',[])
result={'result':'PASS' if all(x.get('http')==200 and x.get('marker',True) for x in checks) else 'FAIL','mic_allowed_in_policy':any('microphone=(self)' in x for x in pol) and not any('microphone=()' in x for x in pol),'checks':checks}
print(json.dumps(result))
